/**
 * `--format agent`: the scan as one JSON document a coding agent can act on.
 *
 * `--json` is the {@link ScanResult} contract, unchanged, for dashboards and CI
 * baselines. This is a different reader. An agent that ran
 * `npx @rebasepro/rls-check` against the database it is building wants, for
 * every finding, the object to change, the statement that changes it, the blanks
 * it must fill first, and — when the object is generated by Rebase — the rule to
 * edit instead. So each finding carries a {@link Remediation}, computed from the
 * snapshot rather than parsed out of the human-oriented `fix` text.
 *
 * Stability rules, because this is parsed:
 *
 * - Every key is always present. An absent object is `null`, never a missing
 *   key, so a parser never has to guess which shape it got.
 * - `formatVersion` changes when a key is renamed or removed. Adding a key
 *   does not change it.
 * - Findings are ordered as `--json` orders them, and `key` identifies one
 *   finding across runs, so an agent can tell "fixed" from "still there".
 * - No ANSI, no prose outside string values, nothing on stdout but the document.
 */
import { compareFindings, exceedsThreshold, exitVerdict } from "./report";
import { remediationFor, type Remediation } from "./remediation";
import type { DbSnapshot, Finding, ScanResult, Severity } from "./types";

/** Bumped when a key is renamed or removed; adding one does not bump it. */
export const AGENT_FORMAT_VERSION = 1;

export interface AgentFinding {
    /**
     * Stable across runs: `<checkId>:<schema>.<object>[:<policy>][:<column>]`.
     * The same finding on the next scan has the same key.
     */
    key: string;
    /** One of the ids `--list-checks` prints. */
    checkId: string;
    severity: Severity;
    confidence: Finding["confidence"];
    /** At or above `--fail-on`: this finding alone makes the run exit 1. */
    failsRun: boolean;
    target: {
        schema: string;
        table: string | null;
        policy: string | null;
        view: string | null;
        routine: string | null;
        column: string | null;
    };
    title: string;
    detail: string;
    impact: string;
    docs: string | null;
    remediation: Remediation;
}

export interface AgentReport {
    tool: "@rebasepro/rls-check";
    format: "agent";
    formatVersion: number;
    version: string;
    /** How to use `findings[].remediation`, in one paragraph. */
    howToApply: string;
    scannedAt: string;
    database: ScanResult["database"];
    serverVersion: string;
    platform: ScanResult["platform"];
    exposedRoles: string[];
    verdict: { exitCode: number; reason: string; failOn: Severity | "none" };
    /** False when a catalogue read or a check failed: no finding is not "clean". */
    complete: boolean;
    /** Facts that change how far the findings can be trusted, in sentences. */
    notes: string[];
    diagnostics: ScanResult["diagnostics"];
    summary: {
        findings: number;
        failing: number;
        bySeverity: Record<Severity, number>;
    };
    findings: AgentFinding[];
}

export interface AgentRenderOptions {
    failOn: Severity | "none";
    version: string;
}

const HOW_TO_APPLY =
    "For each finding, read remediation.apply. \"sql\": replace every token listed in remediation.placeholders, " +
    "then run remediation.sql as a migration. \"rebase-config\": the object is generated by Rebase from a " +
    "collection's securityRules and would be re-made on the next boot, so edit the rules as " +
    "remediation.rebase.snippet shows and run `rebase db push`. \"manual\": remediation.summary names the " +
    "decision to make. Read remediation.caveats before applying; remediation.alternatives are fixes for a " +
    "different intent. Re-run rls-check afterwards: a fixed finding's key is gone.";

export function findingKey(finding: Finding): string {
    const { schema, table, view, routine, policy, column } = finding.target;
    const object = view ?? table ?? (routine ? `${routine}()` : "");
    return [
        `${finding.id}:${schema}${object ? `.${object}` : ""}`,
        ...(policy ? [policy] : []),
        ...(column ? [column] : [])
    ].join(":");
}

function notesFor(result: ScanResult): string[] {
    const notes: string[] = [];
    if (result.scannerIsPrivileged) {
        notes.push(
            "The scan connected as a role row-level security cannot constrain (superuser, owner or BYPASSRLS): " +
            "the findings describe what other roles get, not this connection."
        );
    }
    const scanningAs = result.diagnostics?.scanningAsExposedRole;
    if (scanningAs) {
        notes.push(
            `The scan connected as "${scanningAs}", which row-level security constrains, so it was treated as a ` +
            "role an untrusted caller can arrive as."
        );
    }
    const degraded = result.diagnostics?.degraded ?? [];
    if (degraded.length > 0) {
        notes.push(
            `The scan was incomplete: ${degraded.length} catalogue read(s) or check(s) failed (see ` +
            "diagnostics.degraded). Missing findings are not evidence of a clean database."
        );
    }
    const unrecognized = result.diagnostics?.unrecognizedGrantees ?? [];
    if (unrecognized.length > 0) {
        notes.push(
            `Roles ${unrecognized.join(", ")} can read or write scanned tables and were not assessed. If the ` +
            `application connects as one of them, re-run with --role ${unrecognized[0]}.`
        );
    }
    if (result.diagnostics?.tlsVerificationDisabled) {
        notes.push("TLS certificate verification was turned off to connect.");
    }
    return notes;
}

/**
 * The agent document. Needs the snapshot as well as the result: a remediation
 * names columns, grants and policy expressions that the result does not carry.
 */
export function renderAgentReport(result: ScanResult, snapshot: DbSnapshot, options: AgentRenderOptions): string {
    const sorted = [...result.findings].sort(compareFindings);
    const verdict = exitVerdict(result, options.failOn);
    const bySeverity: Record<Severity, number> = { info: 0, low: 0, medium: 0, high: 0, critical: 0 };
    for (const finding of sorted) bySeverity[finding.severity] += 1;

    const findings: AgentFinding[] = sorted.map((finding) => ({
        key: findingKey(finding),
        checkId: finding.id,
        severity: finding.severity,
        confidence: finding.confidence,
        failsRun: exceedsThreshold([finding], options.failOn),
        target: {
            schema: finding.target.schema,
            table: finding.target.table ?? null,
            policy: finding.target.policy ?? null,
            view: finding.target.view ?? null,
            routine: finding.target.routine ?? null,
            column: finding.target.column ?? null
        },
        title: finding.title,
        detail: finding.detail,
        impact: finding.impact,
        docs: finding.docs ?? null,
        remediation: remediationFor(snapshot, finding)
    }));

    const report: AgentReport = {
        tool: "@rebasepro/rls-check",
        format: "agent",
        formatVersion: AGENT_FORMAT_VERSION,
        version: options.version,
        howToApply: HOW_TO_APPLY,
        scannedAt: result.scannedAt,
        database: result.database,
        serverVersion: result.serverVersion,
        platform: result.platform,
        exposedRoles: result.exposedRoles,
        verdict: { exitCode: verdict.code, reason: verdict.reason, failOn: options.failOn },
        complete: (result.diagnostics?.degraded.length ?? 0) === 0,
        notes: notesFor(result),
        diagnostics: result.diagnostics,
        summary: {
            findings: findings.length,
            failing: findings.filter((f) => f.failsRun).length,
            bySeverity
        },
        findings
    };

    return JSON.stringify(report, null, 2);
}
